    ! * -> RESCoversSpare : if [PL > 0 && Ppv + Pw >= PL && SoC >= 0.95];
    ! * -> RESBatteryDischarge : if [Ppv + Pw < PL && SoC >= 0.2 && PL - Ppv - Pw <= Pbatt_dis_max];
    ! * -> LNGCoversDemand : if [Ppv + Pw < PL && SoC >= 0.2 && PL - Ppv - Pw > Pbatt_dis_max && PL - Ppv - Pw <= eng3_Pmax];
