    [*] -> PLZeroCharge;

    state PLZeroCharge {
        enter {
            Pg_req = 0;
            Pd1_req = 0;
            Pd2_req = 0;
            Pbat_dis = 0;
            Pbat_chg = Ppv + Pw;
            Pspare = 0;
            cmd_LNG_cut_in = 0;
            cmd_LNG_cut_out = 1;
            cmd_DG1_cut_in = 0;
            cmd_DG1_cut_out = 1;
            cmd_DG2_cut_in = 0;
            cmd_DG2_cut_out = 1;
            cmd_load_cut_in = 1;
            cmd_load_cut_out = 0;
