    state LNGDG1CoversDemand {
        enter {
            Pg_req = eng3_Pmax;
            Pd1_req = PL - Ppv - Pw - eng3_Pmax;
            Pd2_req = 0;
            Pbat_dis = 0;
            Pbat_chg = 0;
